import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { CatzPrint, SignatureVerificationError, constructEvent, generateTestHeader, verifyWebhook, webhooks } from "../../src/index.js";

interface Vector {
  name: string;
  secret: string;
  body: string;
  header: string;
  now: number;
}
// Generated by scripts/webhook_vectors.go with the server's SignWebhook.
const vectors: Vector[] = JSON.parse(readFileSync(new URL("../vectors/webhooks.json", import.meta.url), "utf8"));
const v = (name: string) => vectors.find((x) => x.name === name)!;

describe("webhooks.verify (Go SignWebhook vectors)", () => {
  for (const name of ["valid", "valid_unicode", "valid_clock_skew_future", "valid_at_tolerance_edge", "valid_multiple_v1"]) {
    it(`accepts ${name}`, () => {
      const x = v(name);
      const ev = webhooks.verify(x.body, x.header, x.secret, { now: x.now });
      expect(ev).toEqual(JSON.parse(x.body));
      // Bytes work the same as strings.
      expect(webhooks.verify(Buffer.from(x.body), x.header, x.secret, { now: x.now })).toEqual(ev);
    });
  }

  it("parses the event", () => {
    const x = v("valid");
    const ev = webhooks.constructEvent<{ job: { id: string; status: string } }>(x.body, x.header, x.secret, { now: x.now });
    expect(ev.type).toBe("job.printed");
    expect(ev.data.job.status).toBe("printed");
  });

  for (const [name, why] of [
    ["tampered", /No signature matches/],
    ["expired", /tolerance/],
    ["wrong_secret", /No signature matches/],
    ["malformed_header", /no timestamp/],
  ] as const) {
    it(`rejects ${name}`, () => {
      const x = v(name);
      expect(() => webhooks.verify(x.body, x.header, x.secret, { now: x.now })).toThrow(SignatureVerificationError);
      expect(() => webhooks.verify(x.body, x.header, x.secret, { now: x.now })).toThrow(why);
    });
  }

  it("accepts an expired signature when tolerance is widened", () => {
    const x = v("expired");
    expect(() => webhooks.verify(x.body, x.header, x.secret, { now: x.now, tolerance: 600 })).not.toThrow();
    expect(() => webhooks.verify(x.body, x.header, x.secret, 600)).toThrow(/tolerance/); // real clock: years later
  });

  it("rejects a missing header, empty secret, and parsed objects", () => {
    const x = v("valid");
    expect(() => webhooks.verify(x.body, undefined, x.secret)).toThrow(/Missing/);
    expect(() => webhooks.verify(x.body, x.header, "", { now: x.now })).toThrow(/secret/);
    expect(() => webhooks.verify(JSON.parse(x.body), x.header, x.secret, { now: x.now })).toThrow(/raw request body/);
    expect(() => webhooks.verify(x.body, "t=abc,v1=00", x.secret, { now: x.now })).toThrow(/invalid timestamp/);
    expect(() => webhooks.verify(x.body, "t=1760600000", x.secret, { now: 1760600000 })).toThrow(/no v1/);
  });

  it("round-trips generateTestHeader, and aliases agree", () => {
    const body = JSON.stringify({ type: "job.created", data: {} });
    const header = generateTestHeader({ payload: body, secret: "s3cret" });
    expect(verifyWebhook(body, header, "s3cret").type).toBe("job.created");
    expect(constructEvent(body, header, "s3cret").type).toBe("job.created");
    const client = new CatzPrint({ apiKey: "cz_test_x", baseUrl: "http://127.0.0.1:1" });
    expect(client.webhooks.verify(body, header, "s3cret").type).toBe("job.created");
  });
});

describe("webhooks hardening", () => {
  it("a NaN tolerance doesn't disable the replay check", () => {
    const secret = "whsec_test";
    const body = "{}";
    const header = generateTestHeader({ payload: body, secret, timestamp: 1000 });
    expect(() => webhooks.verify(body, header, secret, { tolerance: Number.NaN, now: 100_000 })).toThrow(SignatureVerificationError);
    expect(() => webhooks.verify(body, header, secret, { tolerance: Number.NaN, now: 1001 })).not.toThrow();
  });

  it("rejects absurd timestamps", () => {
    expect(() => webhooks.verify("{}", "t=" + "9".repeat(40) + ",v1=" + "0".repeat(64), "whsec_x")).toThrow(SignatureVerificationError);
  });

  it("exposes the delivery id (event.id) for deduplication", () => {
    const body = '{"id":"dlv_01HZX","type":"ping","created_at":"2026-10-17T00:00:00Z","org_id":"o","data":{}}';
    const header = generateTestHeader({ payload: body, secret: "whsec_x" });
    expect(webhooks.verify(body, header, "whsec_x").id).toBe("dlv_01HZX");
    const x = v("valid");
    expect(webhooks.verify(x.body, x.header, x.secret, { now: x.now }).id).toBeUndefined();
  });
});
